const params = new URLSearchParams(location.search);
const settings = document.getElementById('settings-dialog');
const consent = document.getElementById('consent-dialog');
document.getElementById('open-settings').addEventListener('click', () => settings.showModal());
document.getElementById('save-settings').addEventListener('click', () => settings.close('saved'));
document.getElementById('cancel-settings').addEventListener('click', () => settings.close('cancelled'));
document.getElementById('accept-cookies').addEventListener('click', () => consent.close('accepted'));
document.getElementById('cancel-cookies').addEventListener('click', () => consent.close('cancelled'));
if (params.get('variant') === 'open') consent.showModal();

